function maxLen(arr) {
  const first = new Map([[0, -1]]);                  // prefix sum -> first index it appeared
  let sum = 0, best = 0;
  for (let i = 0; i < arr.length; i++) {
    sum += arr[i];
    if (first.has(sum)) {
      best = Math.max(best, i - first.get(sum));      // same sum again: zero in between
    } else {
      first.set(sum, i);                              // remember only the FIRST index
    }
  }
  return best;
}

def max_len(arr):
    first = {0: -1}                              # prefix sum -> first index it appeared
    total = best = 0
    for i, x in enumerate(arr):
        total += x
        if total in first:
            best = max(best, i - first[total])   # same sum again: zero in between
        else:
            first[total] = i                     # remember only the FIRST index
    return best

int maxLen(int[] arr) {
    Map<Integer, Integer> first = new HashMap<>();      // prefix sum -> first index it appeared
    first.put(0, -1);
    int sum = 0, best = 0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
        if (first.containsKey(sum)) {
            best = Math.max(best, i - first.get(sum));  // same sum again: zero in between
        } else {
            first.put(sum, i);                          // remember only the FIRST index
        }
    }
    return best;
}

int maxLen(vector<int>& arr) {
    unordered_map<int, int> first{{0, -1}};            // prefix sum -> first index it appeared
    int sum = 0, best = 0;
    for (int i = 0; i < (int)arr.size(); i++) {
        sum += arr[i];
        auto it = first.find(sum);
        if (it != first.end()) {
            best = max(best, i - it->second);           // same sum again: zero in between
        } else {
            first[sum] = i;                             // remember only the FIRST index
        }
    }
    return best;
}
